+export const PROJECT_ENTRY_LIMIT = 1_000;
+export const PROJECT_FILE_READ_LIMIT_BYTES = 1024 * 1024;
+const BINARY_SNIFF_BYTES = 8 * 1024;
+const HIDDEN_ENTRIES = new Set([".git"]);
+
+export type ProjectEntry = {
+	name: string;
+	path: string;
+	kind: "file" | "directory";
